def find_dataset_sota(dataset_id, 
                      dataset_pipelines, 
                      pipeline_evaluations):
    """Function that finds SOTA run for a given dataset"""

    #print(dataset_id, dataset_pipelines)

    max_eval, min_time = float('-inf'), float('+inf')
    reject_metric = True
    classification_metric = "test_f1"
    regression_metric = "test_r2"

    for run in dataset_pipelines:
        if str(run) not in pipeline_evaluations[dataset_id]: continue
        evaluation = pipeline_evaluations[dataset_id][str(run)]
        # print(evaluation)
        if evaluation["run_success"] is True:
            if classification_metric in evaluation["run_metrics"]:
                max_eval = max(max_eval, evaluation["run_metrics"][classification_metric])
            else:
                max_eval = max(max_eval, evaluation["run_metrics"][regression_metric])
            min_time = min(min_time, evaluation["run_metrics"]["fit_time"])
            reject_metric = False
        
        #Perfect pipelines are not considered for evaluation (rare but can happen)
        if max_eval > 0.999: reject_metric = True

    return max_eval, min_time, reject_metric

def check_if_sota_perf(dataset_id,
                            rec_datasets,
                            pipeline_evaluations, 
                            valid_runs):
    """Function that checks if a recommended dataset's associated pipeline can outperform SOTA for
    the query dataset"""
    
    dataset_pipelines = valid_runs[dataset_id]

    rec_pipelines = []
    for rec_dataset in rec_datasets: rec_pipelines.extend(valid_runs[rec_dataset])

    dataset_sota, sota_time, reject_metric = find_dataset_sota(dataset_id, dataset_pipelines, pipeline_evaluations)

    classification_metric = "test_f1"
    regression_metric = "test_r2"

    for run in rec_pipelines:
        if str(run) not in pipeline_evaluations[dataset_id]: continue
        evaluation = pipeline_evaluations[dataset_id][str(run)]
        if evaluation["run_success"] is True:
            if classification_metric in evaluation["run_metrics"]:
                if evaluation["run_metrics"][classification_metric] > dataset_sota:
                    diff = evaluation["run_metrics"][classification_metric] - dataset_sota
                    return True, reject_metric, diff, "f1"
                
            else:
                if evaluation["run_metrics"][regression_metric] > dataset_sota:
                    diff = evaluation["run_metrics"][regression_metric] - dataset_sota
                    return True, reject_metric, diff, "r2"
    
    return False, reject_metric, None, None

def evaluate_perf_increase(dataset_id,
                          recommendation_dict,
                          retrieval_method,
                          ks,
                          sota_perf_dict,
                          pipeline_evaluations, 
                          valid_runs):
    
    """Function that evaluates performance increase using pipelines from recommended datasets."""

    sorted_sim_scores = sorted(recommendation_dict.items(), key=lambda x: x[1], reverse=True)

    for k in ks:
        rec_datasets = [score[0] for score in sorted_sim_scores[:k]]
        
        sota_perf, reject_metric, diff, measure = check_if_sota_perf(dataset_id,
                                                                    rec_datasets,
                                                                    pipeline_evaluations, 
                                                                    valid_runs)
        #print(sota_perf)
        if sota_perf and not reject_metric: 
            sota_perf_dict[retrieval_method]["sota_perf"][k] += 1
            sota_perf_dict[retrieval_method]["sota_diff"][measure][k]["min"] = min(sota_perf_dict[retrieval_method]["sota_diff"][measure][k]["min"], diff)
            sota_perf_dict[retrieval_method]["sota_diff"][measure][k]["max"] = max(sota_perf_dict[retrieval_method]["sota_diff"][measure][k]["max"], diff)
            sota_perf_dict[retrieval_method]["sota_diff"][measure][k]["avg"] += diff
            sota_perf_dict[retrieval_method]["sota_diff"][measure][k]["n_success"] += 1
        #print(sota_perf_dict)

    return sota_perf_dict, reject_metric


